<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter,RouterLink} from 'vue-router';import {LogOut,Package,MapPin,UserRound,Plus,Pencil,Trash2} from 'lucide-vue-next';import {api,idr} from '../api';import {useSession,useUi} from '../stores';const props=defineProps<{tab:'orders'|'addresses'|'profile'}>();const session=useSession(),ui=useUi(),router=useRouter(),orders=ref<any[]>([]),addresses=ref<any[]>([]),loading=ref(true),error=ref(''),editing=ref<any>(null),name=ref('');const blank=()=>({recipientName:'',phone:'',addressLine:'',city:'',province:'',postalCode:'',isDefault:false});async function load(){loading.value=true;if(!session.user){await session.load();if(!session.user)return router.push('/login')}name.value=session.user.name;try{if(props.tab==='orders')orders.value=await api('/orders');if(props.tab==='addresses')addresses.value=await api('/addresses')}catch(e:any){error.value=e.message}finally{loading.value=false}}async function logout(){await session.logout();router.push('/')}async function saveProfile(){try{session.user=await api('/auth/me',{method:'PATCH',body:JSON.stringify({name:name.value})});ui.toast('Profile updated')}catch(e:any){ui.toast(e.message,'error')}}function newAddress(){editing.value=blank()}async function saveAddress(){try{const method=editing.value.id?'PATCH':'POST',path=editing.value.id?`/addresses/${editing.value.id}`:'/addresses';await api(path,{method,body:JSON.stringify(editing.value)});editing.value=null;ui.toast('Address saved');load()}catch(e:any){ui.toast(e.message,'error')}}async function removeAddress(id:string){if(!confirm('Delete this address?'))return;try{await api(`/addresses/${id}`,{method:'DELETE'});ui.toast('Address deleted');load()}catch(e:any){ui.toast(e.message,'error')}}onMounted(load);</script>
<template><main class="account-page container"><header class="account-head"><div class="avatar">{{session.user?.name.split(' ').map(v=>v[0]).slice(0,2).join('').toUpperCase()}}</div><div><h1>{{session.user?.name}}</h1><p>{{session.user?.email}} · Shopora Member</p></div><button class="btn-secondary" @click="logout"><LogOut :size="14"/> Sign Out</button></header><nav class="account-tabs"><RouterLink to="/account/orders"><Package :size="15"/> Order History</RouterLink><RouterLink to="/account/addresses"><MapPin :size="15"/> Addresses</RouterLink><RouterLink to="/account/profile"><UserRound :size="15"/> Personal Profile</RouterLink></nav><p v-if="error" class="alert error">{{error}}</p><div v-if="loading" class="skeleton account-skeleton"></div><section v-else-if="tab==='orders'" class="account-content"><div v-if="!orders.length" class="empty-state"><Package :size="45"/><h3>No orders yet</h3><p>Your first considered purchase is waiting.</p><RouterLink class="btn-primary" to="/products">Explore Products</RouterLink></div><article v-for="o in orders" class="order-card"><header><div><b>{{o.orderNumber}}</b><span>Placed {{new Date(o.createdAt).toLocaleDateString('id-ID')}}</span></div><div><span class="status" :class="o.paymentStatus.toLowerCase()">{{o.paymentStatus}}</span><span class="status fulfillment">{{o.fulfillmentStatus}}</span></div></header><div><div class="order-products"><span v-for="i in o.items.slice(0,3)"><b>{{i.productName}}</b><small>Qty {{i.quantity}} · {{idr(i.lineTotal)}}</small></span></div><strong>{{idr(o.totalAmount)}}</strong><RouterLink class="btn-secondary" :to="`/account/orders/${o.id}`">View Details</RouterLink></div></article></section><section v-else-if="tab==='addresses'" class="account-content"><div class="content-heading"><div><h2>Shipping Addresses</h2><p>Manage destinations used during checkout.</p></div><button class="btn-primary" @click="newAddress"><Plus :size="14"/> Add Address</button></div><div v-if="!addresses.length" class="empty-state"><MapPin :size="45"/><h3>No address saved</h3><p>Add an address to speed up checkout.</p></div><div class="address-grid"><article v-for="a in addresses" class="address-card"><em v-if="a.isDefault">Default</em><h3>{{a.recipientName}}</h3><p>{{a.addressLine}}<br/>{{a.city}}, {{a.province}} {{a.postalCode}}<br/>{{a.phone}}</p><div><button @click="editing={...a}"><Pencil :size="14"/> Edit</button><button @click="removeAddress(a.id)"><Trash2 :size="14"/> Delete</button></div></article></div></section><section v-else class="account-content"><div class="surface profile-card"><h2>Personal Profile</h2><p>Keep your account information up to date.</p><form @submit.prevent="saveProfile"><label>Full Name<input v-model="name" required minlength="2"/></label><label>Email Address<input :value="session.user?.email" disabled/></label><button class="btn-primary">Save Changes</button></form></div></section><Teleport to="body"><div v-if="editing" class="modal-shell"><button class="modal-backdrop" @click="editing=null"></button><form class="modal-card" @submit.prevent="saveAddress"><header><div><small>ADDRESS BOOK</small><h2>{{editing.id?'Edit Address':'Add New Address'}}</h2></div><button type="button" @click="editing=null">×</button></header><div class="field-grid"><label>Recipient Name<input v-model="editing.recipientName" required/></label><label>Phone<input v-model="editing.phone" required/></label><label class="full">Street Address<input v-model="editing.addressLine" required/></label><label>City<input v-model="editing.city" required/></label><label>Province<input v-model="editing.province" required/></label><label>Postal Code<input v-model="editing.postalCode" required/></label><label class="check"><input v-model="editing.isDefault" type="checkbox"/> Set as default</label></div><footer><button type="button" class="btn-secondary" @click="editing=null">Cancel</button><button class="btn-primary">Save Address</button></footer></form></div></Teleport></main></template>
